import { useCallback, useState } from 'react';
import { JxButton, JxDrawer, JxDivider } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavMenuProps {
  onNavigate: (key: NavKey) => void;
}

const ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function NavMenu({ onNavigate }: NavMenuProps) {
  const [open, setOpen] = useState(false);

  const select = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  return (
    <>
      <JxButton variant="primary" onClick={() => setOpen(true)}>
        Меню
      </JxButton>

      <JxDrawer
        open={open}
        onOpenChange={setOpen}
        placement="left"
        title="Навигация"
      >
        <nav
          aria-label="Навигация"
          style={{ display: 'grid', gap: 'var(--jx-space-2)' }}
        >
          {ITEMS.map((item) => (
            <JxButton
              key={item.key}
              variant="ghost"
              onClick={() => select(item.key)}
            >
              {item.label}
            </JxButton>
          ))}

          <JxDivider />

          <JxButton variant="danger" onClick={() => select('logout')}>
            Выйти
          </JxButton>
        </nav>
      </JxDrawer>
    </>
  );
}

